cat > /tmp/probe-go-scopes/sample.go <<'EOF'
package main

// line comment
/* block
   comment */
import (
	"fmt"
	alias "os"
	_ "net/http"
)

type MyInt int

type Alias = string

type MyStruct struct {
	Name string `json:"name" xml:"name"`
	Age  int
}

type MyInterface interface {
	DoThing(x int) string
}

const Pi = 3.14
const (
	A = 1
	B = 2
)

var GlobalVar = 42
var (
	X int
	Y string
)

func init() {
	fmt.Println("init")
}

func freeFunc(a, b int) int {
	return a + b
}

func (s MyStruct) DoThing(x int) string {
	defer fmt.Println("deferred")
	go fmt.Println("goroutine")
	var local = "localstr"
	switch x {
	case 1:
		goto End
	default:
		select {
		case <-make(chan int):
		default:
		}
	}
End:
	fmt.Printf("%v %v", local, s.Name)
	return "done"
}

func Generic[T any, U comparable](t T, u U) T {
	expr := t
	return expr
}
EOF
wc -l /tmp/probe-go-scopes/sample.go

