// line comment
/* block
   comment */
/// doc comment line
//! inner doc comment
/** block doc */
use std::collections::HashMap;
use crate::foo as bar;
use std::io::*;

#[derive(Debug)]
#[cfg(feature = "x")]
struct PrivStruct {
    field: i32,
}

pub struct PubStruct(String);

pub(crate) struct PubCrateStruct;
pub(self) struct PubSelfStruct;
pub(super) struct PubSuperStruct;
pub(in crate::foo) struct PubInStruct;

enum PrivEnum { A, B(i32), C { x: f64 } }
pub enum PubEnum {
    Variant1,
    Variant2(u8),
    Variant3 { named: bool },
}

fn priv_fn() { let x = 1; }
pub fn pub_fn() {}
pub(crate) fn pub_crate_fn() {}
pub(self) fn pub_self_fn() {}
pub(super) fn pub_super_fn() {}
const fn const_fn() -> i32 { 42 }
async fn async_fn() {}
unsafe fn unsafe_fn() {}
extern "C" fn extern_fn() {}
pub const unsafe extern "C" fn combo_fn() {}

#[test]
fn test_fn() { assert_eq!(1, 1); }

#[rstest]
fn rstest_fn() {}

trait PrivTrait { fn method(&self); }
pub trait PubTrait: Sized { fn do_it(&self) -> i32 { 0 } }

struct Target;
impl Target {
    fn impl_priv_fn(&self) {}
    pub fn impl_pub_fn(&self) {}
}
impl PubTrait for Target {
    fn do_it(&self) -> i32 { 1 }
}

mod private_mod {
    fn nested_fn() {}
}
pub mod public_mod {}
#[cfg(test)]
mod tests {
    fn test_helper() {}
}

type MyAlias = HashMap<String, i32>;
union MyUnion { i: i32, f: f32 }

fn main() {
    let s = "hello world";
    let raw = r#"raw string"#;
    let bytes = b"byte string";
    let c: char = 'x';
    let f = format!("interp {}", s);
    let closure = |x: i32| x + 1;
    let big = |y| { y * 2 };
    unsafe { let p = 0 as *const i32; }
    let id: MyAlias = HashMap::new();
    let n = unsafe_fn();
}

