   comment */
import { foo } from "mod1";
import * as ns from 'mod2';
import def from `mod3`;
export { foo };
export default function main() {}

const STR = "double";
const TPL = `template ${STR} end`;
let x = 1, y = 2;
var v = 3;

type Alias = string | number;
interface Shape {
  area(): number;
  name: string;
}
enum Color {
  Red,
  Green = 2,
}
namespace NS {
  export const inner = 1;
}

async function afn(a: number): Promise<void> {
  await Promise.resolve(a);
}
function sfn<T>(p: T): T {
  return p;
}
const arrow = async () => {};

class Klass<T> {
  private field: T;
  constructor(f: T) {
    this.field = f;
  }
  method(arg: string): void {
    try {
      throw new Error(arg);
    } catch (e) {
      console.log(e);
    } finally {
      console.log("done");
    }
  }
  async amethod() {}
}

