#include <stdio.h>
#include "local.h"

typedef unsigned int uint32;
typedef struct { int a; } Anon;

enum Color { RED, GREEN = 2 };

struct Point {
  int x;
  int y;
};

union Value {
  int i;
  float f;
};

int global = 42;
static const char *name = "hi";

int add(int a, int b);

static void helper(void) {
  printf("in helper %d\n", global);
}

int add(int a, int b) {
  int sum = a + b;
  return sum;
}

int main(void) {
  int count = 0;
  for (int i = 0; i < 10; i++) {
    count += add(i, 1);
  }
  while (count > 100) {
    count--;
  }
  do {
    count++;
  } while (count < 0);
  if (count > 5) {
    printf("big\n");
  } else {
    printf("small\n");
  }
  switch (count) {
  case 1:
    break;
  default:
    break;
  }
  helper();
  return 0;
}

