 /* outer /* nested */ end */ }
' | $BIN --rust comments -d '.*' | cat -A
echo '=== doc-comments variants ==='
printf '/// outer
//! inner
/** blockdoc */
/*! innerblock */
fn f() {}
' | $BIN --rust doc-comments -d '.*' | cat -A

